<script setup>import { Head,Link } from '@inertiajs/vue3'; import AppLayout from '../../../Layouts/AppLayout.vue'; defineProps({course:Object,summary:Object}); const label=s=>({completed:'تکمیل‌شده',in_progress:'در حال یادگیری',not_started:'مشاهده‌نشده'}[s]);</script>
